from __future__ import annotations
import logging
import os
import re
import shlex
from pathlib import Path
from typing import Union, Optional

from taf.transport.ssh.connection import SSHConnection
from taf.transport.ssh.exceptions import (
    CommandExecutionError,
    CommandOutputCollectionTerminationError,
    CommandOutputTimeoutError
)
from taf.transport.ssh.process import SSHProcess

from .exception import InvalidRequestedAddressError, IpAndPortBindingError, StopSyslogError, SyslogInitializationError
from .filecollector import FileCollector
from .util import retry
from .env_resolver import EnvironmentResolver


class Controller:
    """A class for preparing the environment and starting/stopping the syslog."""

    def __init__(
        self,
        log_dir: str,
        log_name: str,
        ip: str,
        ports: list[int],
        file_limit: int,
        add_line_number: bool = False,
        cli_prefix: str | None = None,
        virtualenv_dir: str | None = None,
        temp_dir: Path = Path("/tmp"),
    ):
        """
        :param str          log_dir:               Path to the directory where syslog should be stored.
        :param str          log_name:              Name of the log file where captured data should be stored.
        :param str          ip:                    IP address of the BTS.
        :param list         ports:                 List of ports to listen on.
        :param int          file_limit:            Max. size of log file. 0 means unlimited.
        :param bool         add_line_number:       Adds line numbers to the generated logs. Defaults to False
        :param str          cli_prefix:            Prefix for the CLI command. Defaults to None.
        :param str          virtualenv_dir:        Path to virtualenv directory to use. Defaults to None.
        :param Path         temp_dir:              Allows to override the default /tmp
        """
        self._log_dir = log_dir
        self._log_name = log_name
        self._file_limit = file_limit
        self._log_path = os.path.join(self._log_dir, self._log_name)
        self._ip = ip
        self._ports = ports
        self._add_line_number = add_line_number
        self._pids = None
        self._cli_prefix = f"{cli_prefix} " if cli_prefix else ""
        self._virtualenv_dir = virtualenv_dir
        self._filecollector = FileCollector(temp_dir=temp_dir)
        self._ssh_connection = None
        self._env_command = None
        self._logger = logging.getLogger(__name__)

    def connect(self, ssh_connection: SSHConnection) -> None:
        """Use given ssh_connection object for communication

        :param ssh_connection: existing SSH connection object
        :type ssh_connection: SSHConnection
        """
        self._ssh_connection = ssh_connection
        self._filecollector.connect(ssh_connection)

    @property
    def connection(self) -> SSHConnection:
        """Return the actual SSH client object."""
        return self._ssh_connection

    @property
    def log_path(self) -> str:
        """Return the provide log directory."""
        return os.path.join(self._log_dir, self._log_name)

    @property
    def log_pattern(self) -> str:
        """Return pattern to select all log files."""
        if self._file_limit > 0:
            return self._create_multi_log_pattern()
        return self._log_path

    @property
    def file_collector(self) -> FileCollector:
        return self._filecollector

    def start(self) -> None:
        """Start the syslog service."""
        resolver = EnvironmentResolver(self._ssh_connection, self._virtualenv_dir)
        self._env_command = resolver.resolve()
        self._try_to_start_syslog()

    def _try_to_start_syslog(self) -> None:
        exc, process = self._start_syslog()
        if exc:
            self._stop_and_raise_exception(exc, process)
        self._logger.info(f"Syslog started successfully!\nSyslog PID: {self._pids}")

    @retry(attempts=3)
    def stop(self) -> None:
        """Stop the syslog service."""
        if self._pids is None:
            self._logger.info("Attempting to stop syslog but no instance found.")
        else:
            self._logger.info(f"Attempting to stop syslog (PIDs: {self._pids}) instance...")
            self._ssh_connection.execute(f"kill -9 {' '.join(self._pids)}", timeout=5)
            if self._pids_exist():
                raise StopSyslogError("Syslog can't be stopped!")
            else:
                self._logger.info(f"Syslog (PID: {self._pids}) stopped!")
                self._pids = None

    def configure(self, ip: str = None, ports: list[int] = None) -> None:
        """Configure optional settings for Controller.

        :param str    ip:    Bind IP address.
        :param list   ports: List of ports used to collect syslog data.
        """
        if ip:
            self._ip = ip
        if ports:
            self._ports = ports

    @retry(attempts=3, delay=1)
    def _start_syslog(self) -> Union[tuple[Exception, SSHProcess], None]:
        process = None
        try:
            out = ""
            regexp = re.compile(r"Syslog started!|error: \[Errno \d{1,3}\]|Error")
            syslog_cmd = self._build_syslog_cmd()
            process = self._send_ssh_command(syslog_cmd)
            while not regexp.search(out):
                out += process.read_output_until("\n")
            out += self._get_stderr(process)
            self._logger.debug(f"Output caught:\n{out}")
            self._pids = self._get_pids_from_console_output(out)
            return self._validate_syslog_output(out), process

        except CommandExecutionError as e:
            self._pids = self._get_pids_from_console_output(str(e))
            self._stop_and_raise_exception(SyslogInitializationError(str(e)), process)

        except Exception as e:
            return e, process

    def _get_stderr(self, process: SSHProcess) -> str:
        err_out = ""
        while True:
            try:
                err_out += process.read_error_until("\n", timeout=1)
            except CommandOutputTimeoutError:
                break
        return err_out

    def _validate_syslog_output(self, console_output: str) -> Optional[Exception]:
        if "Errno 98" in console_output:
            netstat_output = self._get_netstat()
            err = f"Ports {self._ports} are already bound by other application(s) or syslog already running"
            return IpAndPortBindingError(f"{err}\n{netstat_output}".strip())
        elif "Errno 99" in console_output:
            return InvalidRequestedAddressError(f"{self._ip} address is missing.")
        elif "Errno" in console_output:
            return SyslogInitializationError("Error in syslog:\n" + console_output)
        elif "Syslog started!" not in console_output:
            return SyslogInitializationError("Unknown error:\n" + console_output)

    def _pids_exist(self) -> bool:
        fields = ("pid", "ppid", "user", "stat", "pcpu", "size", "priority", "comm")
        for pid in self._pids:
            try:
                process = self._send_ssh_command(f"ps -p {pid} -o {','.join(fields)} --no-headers", timeout=1.5)
                out = process.read_output()
                if out:
                    results = re.split(r"\s*", out.strip())
                    self._logger.debug("  ".join([": ".join(i) for i in zip(fields, results)]))
                    return True
            except CommandExecutionError:
                return True
        return False

    def _send_ssh_command(self, cmd: str, timeout: Optional[float] = None) -> SSHProcess:
        self._logger.debug(f"Sending command:\n {cmd}\nWith timeout: {timeout}")
        process = self._ssh_connection.send_command(cmd, timeout=timeout)
        return process

    def _get_pids_from_console_output(self, console_output: str) -> list[str]:
        pids = re.search("(Syslog PIDs: )(.*)", console_output).group(2).strip()
        return pids.split(" ")

    def _stop_and_raise_exception(self, exc: Exception, process: SSHProcess) -> None:
        self.stop()
        if isinstance(exc, CommandOutputCollectionTerminationError):
            message = self._prepare_err_message(exc, process)
            raise SyslogInitializationError(message)
        raise exc

    @staticmethod
    def _prepare_err_message(exc: CommandOutputCollectionTerminationError, process: SSHProcess) -> str:
        error = process.read_error()
        error_msg_template = """
        What we have found in stderr:
            {}"""
        output_msg_template = """
        Output caught so far:
            {}"""
        exc_msg_template = """
        The above error was directly caused by taf.transport.ssh.CommandOutputCollectionTerminationError with this message:
            {}"""
        message = "A problem has occurred during syslog initialization:"
        if exc.message:
            message += exc_msg_template.format(exc.message)
        if error:
            message += error_msg_template.format(error)
        if exc.output_so_far:
            message += output_msg_template.format(exc.output_so_far)
        return message

    def _create_multi_log_pattern(self) -> str:
        result = self._log_path.rsplit(".", maxsplit=1)
        if len(result) > 1:
            return f"{result[0]}_*.{result[1]}"
        return f"{self._log_path}_*"

    @staticmethod
    def _cast_ports(ports: list[int]) -> list[str]:
        return [str(port) for port in ports]

    def _build_syslog_cmd(self) -> str:
        cmd_list = [
            'cli_syslog',
            '-d', self._log_dir,
            '-l', self._log_name,
            '-i', self._ip,
            '-s', str(self._file_limit),
            '-p', *self._cast_ports(self._ports),
        ]
        if self._add_line_number:
            cmd_list.append("-a")
        cmd = shlex.join(cmd_list)
        cmd = self._env_command + self._cli_prefix + cmd
        return cmd

    def _get_netstat(self) -> str:
        netstat_cmd = f"sudo netstat -tulpen | egrep ':{'|:'.join(map(str, self._ports))}'"
        try:
            netstat_table = self._ssh_connection.execute(netstat_cmd)
        except Exception:
            return ""
        zipped_table = self._parse_netstat_table(netstat_table[0] if not isinstance(netstat_table, str) else netstat_table)
        return self._pretty_printed(zipped_table)

    def _parse_netstat_table(self, netstat_table: str) -> zip:
        lines = netstat_table.split("\n")
        protocols, local_ips, pids_and_program_names = (
            ["Protocol"],
            ["Local IP"],
            ["PID/Program Name"],
        )
        for line in (line for line in lines if line):
            columns = line.split()
            protocols.append(columns[0])
            local_ips.append(columns[3])
            pids_and_program_names.append(columns[-1])
        return zip(protocols, local_ips, pids_and_program_names)

    def _pretty_printed(self, zipped_table: zip) -> str:
        fields = "{: <10s}   {: <30s}   {: <10s}"
        txt = '\n'.join(fields.format(*row) for row in zipped_table)
        return (
            "==============================================================\n"
            f"{txt}\n"
            "==============================================================\n"
        )
